const express = require('express');
const crypto = require('crypto');
const app = express();
app.use(express.json());

// JWT implementation for microservice auth
const SECRET = process.env.JWT_SECRET || crypto.randomBytes(32);
const PUBLIC_KEY = process.env.JWT_PUBLIC_KEY || null;

const ALGORITHMS = {
  'HS256': { sign: (data, key) => crypto.createHmac('sha256', key).update(data).digest('base64url'), type: 'hmac', hash: 'sha256' },
  'HS384': { sign: (data, key) => crypto.createHmac('sha384', key).update(data).digest('base64url'), type: 'hmac', hash: 'sha384' },
  'RS256': { sign: (data, key) => crypto.sign('sha256', Buffer.from(data), key).toString('base64url'), type: 'rsa', hash: 'sha256' },
  'none':  { sign: () => '', type: 'none' }
};

function base64urlEncode(obj) {
  return Buffer.from(JSON.stringify(obj)).toString('base64url');
}

function base64urlDecode(str) {
  return JSON.parse(Buffer.from(str, 'base64url').toString());
}

function createToken(payload, algorithm = 'HS256') {
  const header = { alg: algorithm, typ: 'JWT' };
  const headerEnc = base64urlEncode(header);
  const payloadEnc = base64urlEncode(payload);
  const signingInput = `${headerEnc}.${payloadEnc}`;
  const signature = ALGORITHMS[algorithm].sign(signingInput, SECRET);
  return `${signingInput}.${signature}`;
}

// Constant-time comparison that safely handles length mismatch
function safeCompare(a, b) {
  const bufA = Buffer.from(a, 'utf8');
  const bufB = Buffer.from(b, 'utf8');
  if (bufA.length !== bufB.length) {
    return false;
  }
  return crypto.timingSafeEqual(bufA, bufB);
}

// Security: List of algorithms we accept
const ALLOWED_ALGORITHMS = ['HS256', 'HS384'];

function verifyToken(token, options = {}) {
  const parts = token.split('.');
  if (parts.length !== 3) throw new Error('Invalid token format');

  const header = base64urlDecode(parts[0]);
  const payload = base64urlDecode(parts[1]);
  const signature = parts[2];
  const signingInput = `${parts[0]}.${parts[1]}`;

  // Determine which algorithms to allow
  const allowedAlgs = options.algorithms || ALLOWED_ALGORITHMS;

  // Validate algorithm is in allowlist FIRST before any processing
  if (!allowedAlgs.includes(header.alg)) {
    throw new Error(`Algorithm ${header.alg} not allowed`);
  }

  // Validate algorithm is known
  if (!ALGORITHMS[header.alg]) {
    throw new Error(`Unknown algorithm: ${header.alg}`);
  }

  const algDef = ALGORITHMS[header.alg];

  // Verify signature according to the algorithm type
  if (algDef.type === 'hmac') {
    const expectedSig = algDef.sign(signingInput, SECRET);
    if (!safeCompare(signature, expectedSig)) {
      throw new Error('Invalid signature');
    }
  } else if (algDef.type === 'rsa') {
    // Asymmetric algorithms MUST be verified against the public key,
    // never by re-signing with a symmetric secret.
    if (!PUBLIC_KEY) {
      throw new Error('Public key not configured for RSA verification');
    }
    const valid = crypto.verify(
      algDef.hash,
      Buffer.from(signingInput),
      PUBLIC_KEY,
      Buffer.from(signature, 'base64url')
    );
    if (!valid) {
      throw new Error('Invalid signature');
    }
  } else {
    // Any other type (e.g. 'none') is not verifiable and must be rejected.
    throw new Error(`Unsupported algorithm type for verification: ${header.alg}`);
  }

  // Check expiration
  if (payload.exp && Date.now() / 1000 > payload.exp) {
    throw new Error('Token expired');
  }

  return payload;
}

// Middleware
function authMiddleware(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing token' });
  }

  try {
    const token = authHeader.slice(7);
    req.user = verifyToken(token);
    next();
  } catch (err) {
    return res.status(401).json({ error: err.message });
  }
}

// Service-to-service auth with elevated privileges
function serviceAuthMiddleware(req, res, next) {
  const serviceToken = req.headers['x-service-token'];
  if (!serviceToken) {
    return res.status(401).json({ error: 'Missing service token' });
  }

  try {
    // Service tokens may use different algorithms including RS256
    // We extend the allowed list for service-to-service communication
    const serviceAlgorithms = [...ALLOWED_ALGORITHMS, 'RS256'];
    req.serviceIdentity = verifyToken(serviceToken, { 
      algorithms: serviceAlgorithms 
    });
    next();
  } catch (err) {
    return res.status(401).json({ error: err.message });
  }
}

// Internal admin endpoint - requires both user auth and service auth
function internalAdminCheck(req, res, next) {
  if (!req.serviceIdentity || !req.user) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Admin required' });
  }
  next();
}

// Routes
app.post('/auth/login', (req, res) => {
  const { username, password } = req.body;
  // Simulated auth check
  if (username === 'admin' && password === process.env.ADMIN_PASS) {
    const token = createToken({ sub: username, role: 'admin', exp: Math.floor(Date.now()/1000) + 3600 });
    return res.json({ token });
  }
  if (username && password === process.env.USER_PASS) {
    const token = createToken({ sub: username, role: 'user', exp: Math.floor(Date.now()/1000) + 3600 });
    return res.json({ token });
  }
  res.status(401).json({ error: 'Invalid credentials' });
});

app.get('/api/profile', authMiddleware, (req, res) => {
  res.json({ user: req.user });
});

app.get('/api/admin/users', authMiddleware, (req, res) => {
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }
  res.json({ users: ['admin', 'user1', 'user2'] });
});

// Internal service endpoint
app.post('/internal/sync', serviceAuthMiddleware, authMiddleware, internalAdminCheck, (req, res) => {
  res.json({ status: 'synced', data: req.body });
});

app.listen(3000);
